INSERT INTO safety_alerts
SELECT effectivenessrobot, 'High Safety Concern' 
FROM performance_and_safety 
GROUP BY effectivenessrobot 
HAVING SUM(COALESCE((safety_metrics->>'overloads')::int, 0) + COALESCE((safety_metrics->>'collisions')::int, 0) + COALESCE((safety_metrics->>'emergency_stops')::int, 0) + COALESCE((safety_metrics->>'speed_violations')::int, 0)) > 20;

